function evaluate({ trace, datasetItem }) {
  if (!datasetItem || datasetItem.expectedOutput === undefined) {
    throw new Error("Expected dataset output is required");
  }
  function stable(value) {
    if (Array.isArray(value)) return value.map(stable);
    if (value !== null && typeof value === "object") {
      return Object.fromEntries(Object.keys(value).sort().map(key => [key, stable(value[key])]));
    }
    return value;
  }
  const passed = JSON.stringify(stable(trace.output)) === JSON.stringify(stable(datasetItem.expectedOutput));
  return { score: passed ? 1 : 0, passed };
}
